
begin;
create table sim_murid_private.savings_accounts(id uuid primary key default gen_random_uuid(),owner_id uuid not null unique references public.profiles(id),category text not null check(category in('S','G','N')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create index savings_account_creator on sim_murid_private.savings_accounts(created_by);
create table sim_murid_private.savings_transactions(id uuid primary key default gen_random_uuid(),account_id uuid not null references sim_murid_private.savings_accounts(id),transaction_date date not null,kind text not null check(kind in('deposit','withdrawal','reversal')),amount bigint not null check(amount between 1000 and 1000000000000 and amount%1000=0),delta bigint not null,balance_before bigint not null check(balance_before>=0),balance_after bigint not null check(balance_after>=0),reverses_id uuid unique references sim_murid_private.savings_transactions(id),recorded_by uuid not null references public.profiles(id),reason text not null check(length(btrim(reason)) between 1 and 2000),created_at timestamptz not null default now(),check(balance_after=balance_before+delta),check((kind='deposit' and delta=amount and reverses_id is null)or(kind='withdrawal' and delta=-amount and reverses_id is null)or(kind='reversal' and reverses_id is not null and abs(delta)=amount)));
create index savings_account_date on sim_murid_private.savings_transactions(account_id,transaction_date,created_at);
create index savings_recorder on sim_murid_private.savings_transactions(recorded_by);
create trigger savings_immutable before update or delete on sim_murid_private.savings_transactions for each row execute function sim_murid_private.deny_mutation();
create trigger savings_no_truncate before truncate on sim_murid_private.savings_transactions for each statement execute function sim_murid_private.deny_mutation();
create function public.app_savings_access(p_actor uuid,p_session uuid,p_owner uuid) returns boolean language sql stable security invoker set search_path='' as $$select public.app_onboarding_ready(p_actor,p_session) and (public.app_ops_manager(p_actor,p_session,'savings_manager') or public.app_education_task(p_actor,'school_head') or (p_actor=p_owner and (exists(select 1 from public.user_roles where user_id=p_actor and role_code in('student','customer','alumni')) or exists(select 1 from public.user_access_flags where user_id=p_actor and savings_access))) or (public.app_ops_role(p_actor,'parent') and exists(select 1 from sim_murid_private.student_guardians where student_id=p_owner and parent_id=p_actor and revoked_at is null)))$$;
create function public.app_savings_mutate(p_actor uuid,p_session uuid,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare acc uuid;owner uuid;target uuid;row sim_murid_private.savings_transactions%rowtype;amount bigint;bal bigint;old_effect bigint:=0;dt date;kind text;begin
 if not public.app_ops_manager(p_actor,p_session,'savings_manager') then return jsonb_build_object('code','denied');end if;
 if p_command->>'type'='account' then
 owner=(p_command->>'ownerId')::uuid;if not exists(select 1 from public.profiles where id=owner and status='active') then return jsonb_build_object('code','invalid');end if;
 insert into sim_murid_private.savings_accounts(owner_id,category,created_by) values(owner,p_command->>'category',p_actor) returning id into target;
 elsif p_command->>'type' in('transaction','void') then
 target=(p_command->>'id')::uuid;
 if target is not null then
 select * into row from sim_murid_private.savings_transactions st where st.id=target and st.kind<>'reversal';if not found or exists(select 1 from sim_murid_private.savings_transactions where reverses_id=target) then return jsonb_build_object('code','not_found');end if;acc=row.account_id;old_effect=row.delta;
 else acc=(p_command->>'accountId')::uuid;end if;
 perform 1 from sim_murid_private.savings_accounts where id=acc for update;if not found then return jsonb_build_object('code','not_found');end if;
 select coalesce(sum(delta),0) into bal from sim_murid_private.savings_transactions where account_id=acc;
 if p_command->>'type'='transaction' then
 amount=(p_command->>'amount')::bigint;dt=(p_command->>'date')::date;kind=p_command->>'kind';
 if amount is null or amount not between 1000 and 1000000000000 or amount%1000<>0 or dt>public.app_ops_today() or kind not in('deposit','withdrawal') or acc is distinct from (p_command->>'accountId')::uuid then return jsonb_build_object('code','invalid');end if;
 if kind='deposit' and exists(select 1 from sim_murid_private.savings_transactions x where x.account_id=acc and x.kind='deposit' and x.transaction_date=dt and x.id is distinct from target and not exists(select 1 from sim_murid_private.savings_transactions r where r.reverses_id=x.id)) then return jsonb_build_object('code','duplicate');end if;
 if (bal-old_effect+(case when kind='deposit' then amount else -amount end))<0 then return jsonb_build_object('code','insufficient');end if;
 else if target is null then return jsonb_build_object('code','invalid');end if;if bal-old_effect<0 then return jsonb_build_object('code','insufficient');end if;end if;
 -- Correction first removes the old effect, then validates and records the replacement. Every snapshot is immutable.
 if target is not null then
 if bal-old_effect<0 then
 if p_command->>'type'<>'transaction' or kind<>'deposit' then return jsonb_build_object('code','insufficient');end if;
 insert into sim_murid_private.savings_transactions(account_id,transaction_date,kind,amount,delta,balance_before,balance_after,recorded_by,reason) values(acc,dt,kind,amount,amount,bal,bal+amount,p_actor,p_command->>'reason') returning id into target;bal=bal+amount;
 insert into sim_murid_private.savings_transactions(account_id,transaction_date,kind,amount,delta,balance_before,balance_after,reverses_id,recorded_by,reason) values(acc,public.app_ops_today(),'reversal',row.amount,-row.delta,bal,bal-row.delta,row.id,p_actor,p_command->>'reason');
 return jsonb_build_object('code','saved','id',target);end if;
 insert into sim_murid_private.savings_transactions(account_id,transaction_date,kind,amount,delta,balance_before,balance_after,reverses_id,recorded_by,reason) values(acc,public.app_ops_today(),'reversal',row.amount,-row.delta,bal,bal-row.delta,row.id,p_actor,p_command->>'reason');bal=bal-row.delta;
 end if;
 if p_command->>'type'='transaction' then insert into sim_murid_private.savings_transactions(account_id,transaction_date,kind,amount,delta,balance_before,balance_after,recorded_by,reason) values(acc,dt,kind,amount,case when kind='deposit' then amount else -amount end,bal,bal+case when kind='deposit' then amount else -amount end,p_actor,p_command->>'reason') returning id into target;end if;
 else return jsonb_build_object('code','invalid');end if;return jsonb_build_object('code','saved','id',target);end$$;

create function public.app_operations_write(p_actor uuid,p_session uuid,p_request uuid,p_revision bigint,p_module text,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare version bigint;old sim_murid_private.operations_requests%rowtype;result jsonb;before_image jsonb;begin
 perform 1 from public.profiles where id=p_actor for share;perform 1 from public.user_roles where user_id=p_actor for share;
 if not public.app_onboarding_ready(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if not (case p_module when 'duty' then public.app_education_admin(p_actor,p_session) when 'attendance' then public.app_education_admin(p_actor,p_session) or public.app_duty_confirmed(p_actor,public.app_ops_today()) when 'mentoring' then public.app_education_admin(p_actor,p_session) or public.app_education_task(p_actor,'student_mentor') when 'fees' then public.app_ops_manager(p_actor,p_session,'committee_treasurer') when 'savings' then public.app_ops_manager(p_actor,p_session,'savings_manager') else false end) then return jsonb_build_object('code','denied');end if;
 select revision into version from sim_murid_private.operations_state for update;
 select * into old from sim_murid_private.operations_requests where id=p_request;
 if found then if old.actor=p_actor and old.module=p_module and old.command=p_command then return old.result;end if;return jsonb_build_object('code','request_conflict');end if;
 if version is distinct from p_revision then return jsonb_build_object('code','stale');end if;
 if p_module not in('duty','attendance','mentoring','fees','savings') or jsonb_typeof(p_command) is distinct from 'object' or p_command->>'type' is null then return jsonb_build_object('code','invalid');end if;
 if p_command->>'type' in('void','edit','unconfirm','cancel') or (p_command->>'id') is not null then
 if coalesce(length(btrim(p_command->>'reason')),0) not between 3 and 2000 then return jsonb_build_object('code','invalid');end if;end if;
 if p_command->>'id' is not null then
 case p_module when 'duty' then select to_jsonb(t) into before_image from sim_murid_private.teacher_duty_sessions t where id=(p_command->>'id')::uuid;
 when 'attendance' then select to_jsonb(t) into before_image from sim_murid_private.student_attendance t where id=(p_command->>'id')::uuid;
 when 'mentoring' then select to_jsonb(t) into before_image from sim_murid_private.mentoring_reports t where id=(p_command->>'id')::uuid;
 when 'fees' then select to_jsonb(t)||jsonb_build_object('allocations',(select jsonb_agg(a) from sim_murid_private.payment_allocations a where a.payment_id=t.id and a.voided_at is null)) into before_image from sim_murid_private.committee_payments t where id=(p_command->>'id')::uuid;
 when 'savings' then select to_jsonb(t) into before_image from sim_murid_private.savings_transactions t where id=(p_command->>'id')::uuid;end case;end if;
 case p_module
 when 'duty' then result=public.app_duty_mutate(p_actor,p_session,p_command);
 when 'attendance' then result=public.app_attendance_mutate(p_actor,p_session,p_command);
 when 'mentoring' then result=public.app_mentoring_mutate(p_actor,p_session,p_command);
 when 'fees' then result=public.app_fees_mutate(p_actor,p_session,p_command);
 when 'savings' then result=public.app_savings_mutate(p_actor,p_session,p_command);end case;
 if result->>'code'='saved' then
 update sim_murid_private.operations_state set revision=revision+1;
 insert into sim_murid_private.operations_requests(id,actor,module,command,result) values(p_request,p_actor,p_module,p_command,result);
 insert into sim_murid_private.activity_logs(actor_id,actor_kind,action,entity_type,entity_id,request_id,metadata) values(p_actor,'user',p_module||'.'||(p_command->>'type'),p_module,(result->>'id')::uuid,p_request,jsonb_build_object('reason',p_command->>'reason','before',before_image,'command',p_command));
 end if;return result;
exception when unique_violation then return jsonb_build_object('code','duplicate');when invalid_text_representation or check_violation or not_null_violation or foreign_key_violation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then return jsonb_build_object('code','invalid');end$$;
create function public.app_operations_read(p_actor uuid,p_session uuid,p_module text,p_filters jsonb default '{}') returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare startdate date;enddate date;cls uuid;target uuid;pg integer;pagesize integer;result jsonb:='[]';summary jsonb:='{}';people jsonb:='[]';classes jsonb:='[]';extra jsonb:='{}';manage boolean:=false;total integer;effective integer;studentdays integer;population integer;yr integer;begin
 if not public.app_onboarding_ready(p_actor,p_session) or p_module not in('duty','attendance','mentoring','fees','savings') then return null;end if;
 yr=coalesce((p_filters->>'year')::integer,extract(year from public.app_ops_today())::integer);
 if yr not between 2000 and 2100 then return null;end if;
 startdate=coalesce((p_filters->>'start')::date,make_date(yr,1,1));enddate=coalesce((p_filters->>'end')::date,make_date(yr,12,31));cls=(p_filters->>'classId')::uuid;target=(p_filters->>'studentId')::uuid;pg=greatest(1,coalesce((p_filters->>'page')::integer,1));pagesize=case when p_filters->>'export'='true' then 10000 else 50 end;
 if enddate<startdate or enddate-startdate>366 then return null;end if;
 manage=case p_module when 'duty' then public.app_education_admin(p_actor,p_session) when 'attendance' then public.app_education_admin(p_actor,p_session) or public.app_duty_confirmed(p_actor,public.app_ops_today()) when 'mentoring' then public.app_education_admin(p_actor,p_session) or public.app_education_task(p_actor,'student_mentor') when 'fees' then public.app_ops_manager(p_actor,p_session,'committee_treasurer') else public.app_ops_manager(p_actor,p_session,'savings_manager') end;
 select coalesce(jsonb_agg(q order by q.full_name),'[]') into people from (select p.id,p.username,p.full_name,r.role_code,c.id as class_id,c.name as class_name from public.profiles p join public.user_roles r on r.user_id=p.id left join lateral(select e.class_id from sim_murid_private.enrollments e join public.academic_years y on y.id=e.academic_year_id where e.student_id=p.id and e.ended_at is null and y.is_active order by e.created_at desc limit 1)e on true left join public.classes c on c.id=e.class_id
 where p.status='active' and (coalesce(p_filters->>'query','')='' or p.full_name ilike '%'||(p_filters->>'query')||'%' or p.username ilike '%'||(p_filters->>'query')||'%') and
 case p_module when 'duty' then r.role_code='teacher' and (manage or p.id=p_actor)
 when 'savings' then manage or public.app_savings_access(p_actor,p_session,p.id)
 when 'fees' then r.role_code='student' and (manage or public.app_ops_student(p_actor,p_session,p.id))
 when 'mentoring' then (r.role_code='student' and (public.app_ops_student(p_actor,p_session,p.id) or public.app_mentor_access(p_actor,p_session,p.id))) or (r.role_code='teacher' and (public.app_education_admin(p_actor,p_session) or p.id=p_actor))
 else r.role_code='student' and public.app_attendance_access(p_actor,p_session,p.id,c.id,public.app_ops_today(),false) end and (cls is null or c.id=cls) and (target is null or p.id=target) order by p.full_name,p.id limit 2000)q;
 select coalesce(jsonb_agg(q order by q.level,q.name),'[]') into classes from(select c.id,c.name,c.level,c.academic_year_id from public.classes c where c.archived_at is null and (public.app_education_admin(p_actor,p_session) or public.app_education_task(p_actor,'school_head') or manage or public.app_class_access(p_actor,p_session,c.id,false)))q;
 if p_module='duty' then
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'teacher_id',s.teacher_id,'name',p.full_name,'date',s.duty_date,'kind',s.kind,'status',s.status,'replaces_id',s.replaces_id,'notes',coalesce(r.full_name,''),'can_edit',manage and s.duty_date=public.app_ops_today()) order by s.duty_date desc,p.full_name),'[]') into result from sim_murid_private.teacher_duty_sessions s join public.profiles p on p.id=s.teacher_id left join public.profiles r on r.id=s.replaces_id where s.duty_date between startdate and enddate and (manage or s.teacher_id=p_actor);
 extra=jsonb_build_object('roster',(select coalesce(jsonb_agg(jsonb_build_object('teacher_id',r.teacher_id,'name',p.full_name,'weekday',r.weekday)),'[]') from sim_murid_private.teacher_duty_roster r join public.profiles p on p.id=r.teacher_id where manage or r.teacher_id=p_actor),'confirmed',public.app_duty_confirmed(p_actor,public.app_ops_today()));
 elsif p_module='attendance' then
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'student_id',a.student_id,'class_id',a.class_id,'name',p.full_name,'class_name',c.name,'date',a.attendance_date,'status',a.status,'notes',a.notes,'can_edit',public.app_attendance_access(p_actor,p_session,a.student_id,a.class_id,a.attendance_date,true) and (public.app_education_admin(p_actor,p_session) or a.recorded_by=p_actor)) order by a.attendance_date desc,p.full_name),'[]') into result from sim_murid_private.student_attendance a join public.profiles p on p.id=a.student_id join public.classes c on c.id=a.class_id where a.voided_at is null and a.attendance_date between startdate and enddate and (cls is null or a.class_id=cls) and (target is null or a.student_id=target) and (p_filters->>'status' is null or a.status=p_filters->>'status') and public.app_attendance_access(p_actor,p_session,a.student_id,a.class_id,a.attendance_date,false);
 select count(*) into effective from generate_series(startdate,least(enddate,public.app_ops_today()),interval '1 day')d where extract(isodow from d)<>7 and not exists(select 1 from public.holidays h where h.holiday_date=d::date);
 select count(distinct(e.student_id,d::date)),count(distinct e.student_id) into studentdays,population from generate_series(startdate,least(enddate,public.app_ops_today()),interval '1 day')d join sim_murid_private.enrollments e on e.starts_on<=d::date and (e.ended_at is null or (e.ended_at at time zone 'Asia/Jakarta')::date>d::date) join public.academic_years y on y.id=e.academic_year_id where d::date>=make_date(y.start_year,7,1) and d::date<make_date(y.start_year+1,7,1) and extract(isodow from d)<>7 and not exists(select 1 from public.holidays h where h.holiday_date=d::date) and (cls is null or e.class_id=cls) and (target is null or e.student_id=target) and public.app_attendance_access(p_actor,p_session,e.student_id,e.class_id,d::date,false);
 summary=jsonb_build_object('effectiveDays',effective,'effectiveStudentDays',studentdays,'recorded',jsonb_array_length(result),'present',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Hadir'),'sick',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Sakit'),'excused',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Izin'),'absent',(select count(*) from jsonb_array_elements(result)x where x->>'status'='Alpha'));
 -- Both denominators are explicit: recorded rows and effective student-days over the selected population.
 summary=summary||jsonb_build_object('recordedPercent',case when jsonb_array_length(result)>0 then round(100.0*(summary->>'present')::numeric/jsonb_array_length(result),2) else 0 end,'effectivePercent',case when studentdays>0 then round(100.0*(summary->>'present')::numeric/studentdays,2) else 0 end,'studentCount',population);
 extra=jsonb_build_object('holidays',(select coalesce(jsonb_agg(holiday_date),'[]') from public.holidays where holiday_date between startdate and enddate));
 elsif p_module='mentoring' then
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'student_id',r.student_id,'teacher_id',r.teacher_id,'name',p.full_name,'teacher_name',t.full_name,'date',r.report_date,'kind',r.kind,'subject',r.subject,'catalog_id',r.catalog_id,'predicate',r.predicate,'notes',r.notes,'can_edit',public.app_education_admin(p_actor,p_session) or (r.teacher_id=p_actor and public.app_mentor_access(p_actor,p_session,r.student_id))) order by r.report_date desc,r.created_at desc),'[]') into result from sim_murid_private.mentoring_reports r join public.profiles p on p.id=r.student_id join public.profiles t on t.id=r.teacher_id where r.voided_at is null and r.report_date between startdate and enddate and (target is null or r.student_id=target) and (public.app_ops_student(p_actor,p_session,r.student_id) or public.app_mentor_access(p_actor,p_session,r.student_id));
 extra=jsonb_build_object('assignments',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'teacher_id',m.teacher_id,'student_id',m.student_id,'name',p.full_name,'teacher_name',t.full_name)),'[]') from sim_murid_private.mentor_students m join public.profiles p on p.id=m.student_id join public.profiles t on t.id=m.teacher_id where m.revoked_at is null and (public.app_ops_student(p_actor,p_session,m.student_id) or public.app_mentor_access(p_actor,p_session,m.student_id))),'catalog',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name) order by name),'[]') from public.memorization_catalog where active),'canAssign',public.app_education_admin(p_actor,p_session));
 elsif p_module='fees' then
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'student_id',p.student_id,'name',u.full_name,'date',p.payment_date,'notes',p.notes,'amount',(select sum(a.amount) from sim_murid_private.payment_allocations a where a.payment_id=p.id and a.voided_at is null),'allocations',(select jsonb_agg(jsonb_build_object('month',a.month,'amount',a.amount)) from sim_murid_private.payment_allocations a where a.payment_id=p.id and a.voided_at is null),'can_edit',manage) order by p.payment_date desc,p.created_at desc),'[]') into result from sim_murid_private.committee_payments p join public.profiles u on u.id=p.student_id where p.voided_at is null and p.payment_date between startdate and enddate and (target is null or p.student_id=target) and (manage or public.app_ops_student(p_actor,p_session,p.student_id)) and (cls is null or exists(select 1 from jsonb_array_elements(people)x where (x->>'id')::uuid=p.student_id));
 extra=jsonb_build_object('months',(select coalesce(jsonb_agg(jsonb_build_object('student_id',p->>'id','name',p->>'full_name','month',d::date,'status',case when cash.amount is not null then 'paid' when waiver.n>0 then 'waived' else 'unpaid' end,'amount',coalesce(cash.amount,0),'waiverSources',coalesce(waiver.n,0),'tariff',tar.amount,'outstanding',case when cash.amount is not null or waiver.n>0 then 0 else tar.amount end)),'[]') from jsonb_array_elements(people)p cross join generate_series(date_trunc('month',startdate),date_trunc('month',enddate),interval '1 month')d left join sim_murid_private.committee_tariffs tar on tar.class_id=(p->>'class_id')::uuid and tar.month=d::date left join lateral(select a.amount from sim_murid_private.payment_allocations a where a.student_id=(p->>'id')::uuid and a.month=d::date and a.voided_at is null)cash on true left join lateral(select count(*)n from sim_murid_private.payment_allocations a where a.waived_student_id=(p->>'id')::uuid and a.month=d::date and a.voided_at is null)waiver on true));
 summary=jsonb_build_object('cashReceived',coalesce((select sum((x->>'amount')::bigint) from jsonb_array_elements(result)x),0),'waivedMonths',(select count(*) from jsonb_array_elements(extra->'months')x where x->>'status'='waived'),'unpaidMonths',(select count(*) from jsonb_array_elements(extra->'months')x where x->>'status'='unpaid'),'knownOutstanding',coalesce((select sum((x->>'outstanding')::bigint) from jsonb_array_elements(extra->'months')x),0),'unknownTariffs',(select count(*) from jsonb_array_elements(extra->'months')x where x->>'status'='unpaid' and x->>'tariff' is null));
 else
 extra=jsonb_build_object('accounts',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'owner_id',a.owner_id,'name',p.full_name,'category',a.category,'balance',coalesce((select sum(delta) from sim_murid_private.savings_transactions where account_id=a.id),0)) order by p.full_name),'[]') from sim_murid_private.savings_accounts a join public.profiles p on p.id=a.owner_id where public.app_savings_access(p_actor,p_session,a.owner_id) and (target is null or a.owner_id=target)));
 select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'account_id',t.account_id,'student_id',a.owner_id,'name',p.full_name,'date',t.transaction_date,'kind',t.kind,'amount',t.amount,'delta',t.delta,'balance_before',t.balance_before,'balance',t.balance_after,'notes',t.reason,'reverses_id',t.reverses_id,'reversed',exists(select 1 from sim_murid_private.savings_transactions r where r.reverses_id=t.id),'can_edit',manage and t.kind<>'reversal' and not exists(select 1 from sim_murid_private.savings_transactions r where r.reverses_id=t.id)) order by t.created_at desc,t.id),'[]') into result from sim_murid_private.savings_transactions t join sim_murid_private.savings_accounts a on a.id=t.account_id join public.profiles p on p.id=a.owner_id where t.transaction_date between startdate and enddate and (target is null or a.owner_id=target) and public.app_savings_access(p_actor,p_session,a.owner_id);
 summary=jsonb_build_object('balance',coalesce((select sum((x->>'balance')::bigint) from jsonb_array_elements(extra->'accounts')x),0),'periodNet',coalesce((select sum((x->>'delta')::bigint) from jsonb_array_elements(result)x),0),'deposits',coalesce((select sum((x->>'amount')::bigint) from jsonb_array_elements(result)x where x->>'kind'='deposit' and x->>'reversed'='false'),0),'withdrawals',coalesce((select sum((x->>'amount')::bigint) from jsonb_array_elements(result)x where x->>'kind'='withdrawal' and x->>'reversed'='false'),0));
 end if;
 if p_module in('attendance','fees','savings') then extra=extra||jsonb_build_object('trend',coalesce((select jsonb_agg(jsonb_build_object('month',m,'value',v) order by m) from (select left(x->>'date',7)m,sum(case when p_module='attendance' then case when x->>'status'='Hadir' then 1 else 0 end when p_module='savings' then (x->>'delta')::numeric else (x->>'amount')::numeric end)v from jsonb_array_elements(result)x group by left(x->>'date',7))q),'[]'));end if;
 total=jsonb_array_length(result);
 return jsonb_build_object('module',p_module,'today',public.app_ops_today(),'revision',(select revision from sim_murid_private.operations_state),'canManage',manage,'isAdmin',public.app_education_admin(p_actor,p_session),'people',people,'classes',classes,'rows',coalesce((select jsonb_agg(value order by ord) from jsonb_array_elements(result) with ordinality as x(value,ord) where ord>(pg-1)*pagesize and ord<=pg*pagesize),'[]'),'total',total,'page',pg,'pageSize',pagesize,'summary',summary,'extra',extra);
end$$;
-- Private tables are deny-by-default; only the verified server can call these invoker RPCs.
do $$declare t text;r record;begin
 foreach t in array array['operations_state','operations_requests','teacher_duty_roster','teacher_duty_sessions','student_attendance','mentor_students','mentoring_reports','committee_payments','payment_allocations','committee_tariffs','savings_accounts','savings_transactions'] loop
 execute format('alter table sim_murid_private.%I enable row level security',t);
 execute format('revoke all on table sim_murid_private.%I from public,anon,authenticated',t);
 execute format('grant select,insert,update,delete on table sim_murid_private.%I to service_role',t);end loop;
 for r in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'app_ops_%' or p.proname like 'app_operations_%' or p.proname in('app_duty_confirmed','app_duty_mutate','app_attendance_access','app_attendance_mutate','app_mentor_access','app_mentoring_mutate','app_natural_key','app_fee_waiver_student','app_fees_mutate','app_savings_access','app_savings_mutate')) loop
 execute format('revoke all on function %s from public,anon,authenticated',r.signature);execute format('grant execute on function %s to service_role',r.signature);end loop;
end$$;
commit;
